on conflict (slug) do update set
  image_url=excluded.image_url,
  cost_price=excluded.cost_price,
  suggested_price=excluded.suggested_price,
  price=excluded.price,
  stock=excluded.stock,
  origin=excluded.origin,
  gender=coalesce(public.products.gender, excluded.gender),
  volume=coalesce(public.products.volume, excluded.volume),
  short_description=coalesce(public.products.short_description, excluded.short_description);
